<?php

namespace App\Console\Commands;

use Illuminate\Console\Command;
use Illuminate\Support\Facades\Storage;

/**
 * Deletes audio generated by POST /api/tts once it is older than the retention window.
 * Only touches uploads/{userId}/tts/ — never the user's own audio library or any project file.
 */
class PruneTtsFiles extends Command
{
    protected $signature = 'tts:prune {--days= : Override the retention window in days}';

    protected $description = 'Delete API-generated speech files older than the retention window';

    public function handle(): int
    {
        $days = (int) ($this->option('days') ?: config('integrations.tts.retention_days', 7));
        $cutoff = now()->subDays(max(1, $days))->getTimestamp();
        $disk = Storage::disk('media');
        $deleted = 0;

        foreach ($disk->directories('uploads') as $userDir) {
            $ttsDir = $userDir . '/tts';

            foreach ($disk->files($ttsDir) as $file) {
                if ($disk->lastModified($file) < $cutoff && $disk->delete($file)) {
                    $deleted++;
                }
            }
        }

        $this->info("Deleted {$deleted} speech file(s) older than {$days} day(s).");

        return self::SUCCESS;
    }
}
